{
  "name": "clock",
  "description": "Clock",
  "version": "0.0.0",
  "private": true,
  "scripts": {
    "build": "turbo run build",
    "dev": "turbo run dev --parallel",
    "lint": "turbo run lint",
    "format": "prettier --write .",
    "typecheck": "turbo run typecheck",
    "clean": "turbo run clean && rm -rf node_modules"
  },
  "devDependencies": {
    "prettier": "^3.6.2",
    "turbo": "^2.3.3",
    "typescript": "5.9.2"
  },
  "packageManager": "pnpm@10.32.1"
}

import { PrismaClient } from "~/generated/prisma/client";
import { PrismaD1 } from "@prisma/adapter-d1";

export let prisma: ReturnType<typeof createPrisma>;

export const createPrisma = (_db: D1Database) => {
  const adapter = new PrismaD1(_db);
  return new PrismaClient({
    adapter,
    log: ["error"],
  });
};

export const initPrisma = (db: D1Database) => {
  if (prisma) return;
  prisma = createPrisma(db);
};

{
  "name": "@clock/db",
  "version": "0.0.1",
  "type": "module",
  "main": "./src/index.ts",
  "dependencies": {
    "drizzle-orm": "^0.45.2"
  },
  "devDependencies": {
    "drizzle-kit": "^0.31.10"
  }
}

import { betterAuth } from "better-auth";
import { prismaAdapter } from "better-auth/adapters/prisma";
import { prisma } from "./db";
import { getEnv } from "~/worker/env";

const createAuthServer = () =>
  betterAuth({
    database: prismaAdapter(prisma, {
      provider: "sqlite",
    }),
    secret:
      getEnv().BETTER_AUTH_SECRET ||
      "your-better-auth-secret-change-in-production",

    // 信任的来源（用于 CORS）
    trustedOrigins: [
      "http://localhost:4321",
      "http://localhost:4322",
      "chrome-extension://",
    ],

    // Cookie 配置：开发环境使用 lax（允许 http），生产环境使用 none（需要 https）
    advanced: {
      cookies: {
        session_token: {
          attributes: {
            // sameSite: "none" 需要 secure: true，开发环境使用 http，所以用 "lax"
            sameSite: "lax",
            httpOnly: false,
            secure: false,
          },
        },
      },
    },

    emailAndPassword: {
      enabled: true,
    },
    socialProviders: {
      google: {
        clientId: getEnv().GOOGLE_CLIENT_ID || "",
        clientSecret: getEnv().GOOGLE_CLIENT_SECRET || "",
      },
      github: {
        clientId: getEnv().GITHUB_CLIENT_ID || "",
        clientSecret: getEnv().GITHUB_CLIENT_SECRET || "",
      },
      apple: {
        clientId: getEnv().APPLE_CLIENT_ID || "",
        clientSecret: getEnv().APPLE_CLIENT_SECRET || "",
      },
      twitter: {
        clientId: getEnv().TWITTER_CLIENT_ID || "",
        clientSecret: getEnv().TWITTER_CLIENT_SECRET || "",
      },
    },
  });

type AuthServer = ReturnType<typeof createAuthServer>;
let _authServer: AuthServer | undefined;

export const getAuthServer = () => {
  if (_authServer) return _authServer;

  _authServer = createAuthServer();

  return _authServer;
};

import { defineConfig } from 'drizzle-kit';

export default defineConfig({
  schema: 'packages/db/src/schema/test-migration.ts',
  out: 'packages/db/migrations',
  dialect: 'sqlite',
});

import { protectedProcedure, router } from "../trpc";
import { prisma } from "../db";
import { z } from "zod";
import { TRPCError } from "@trpc/server";
import {
  calculateActivityStatus,
  calculateTodayTime,
} from "@clock/utils";
import dayjs from "dayjs";

export const activityRouter = router({
  // 获取特定活动详情
  getActivity: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
        timeRange: z.object({
          start: z.number().describe("开始时间戳，单位：毫秒"),
          end: z.number().describe("结束时间戳，单位：毫秒"),
        }),
      }),
    )
    .query(async ({ ctx, input }) => {
      let _start = dayjs(input.timeRange.start).toDate();
      let _end = dayjs(input.timeRange.end).toDate();

      // 检查是否有未结束的period
      const unfinishedPeriod = await prisma.period.findFirst({
        where: {
          activityId: input.activityId,
          userId: ctx.user.userId,
          end: null,
        },
      });

      if (unfinishedPeriod) {
        const userDate = dayjs(unfinishedPeriod.start).tz(ctx.cookie.timezone);
        _start = userDate.startOf("day").toDate();
        _end = userDate.endOf("day").toDate();
      }

      const activity = await prisma.activity.findUnique({
        where: { id: input.activityId },
        include: {
          periods: {
            where: {
              start: {
                gte: _start,
                lt: _end,
              },
              userId: ctx.user.userId,
            },
            orderBy: {
              start: "asc",
            },
            select: {
              id: true,
              start: true,
              end: true,
              duration: true,
            },
          },
        },
      });

      if (!activity) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "未找到活动",
        });
      }

      if (activity.from !== "system" && activity.userId !== ctx.user.userId) {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "无权访问此活动",
        });
      }

      return {
        id: activity.id,
        name: activity.name,
        emoji: activity.emoji,
        color: activity.color,
        machine: calculateActivityStatus(activity),
        calculatedDate: _start,
        periods: activity.periods,
        todayTime: calculateTodayTime(activity.periods),
      };
    }),

  // 通过tag获取活动
  getByTag: protectedProcedure
    .input(
      z.object({
        tag: z.string(),
      }),
    )
    .query(async ({ ctx, input }) => {
      const activity = await prisma.activity.findFirst({
        where: {
          tag: input.tag,
          OR: [{ from: "system" }, { userId: ctx.user.userId }],
        },
        include: {
          periods: {
            orderBy: {
              start: "asc",
            },
          },
        },
      });

      if (!activity) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "未找到活动",
        });
      }

      return activity;
    }),

  // 获取活动列表
  getList: protectedProcedure.query(async ({ ctx }) => {
    const activities = await prisma.activity.findMany({
      where: {
        OR: [{ from: "system" }, { userId: ctx.user.userId }],
      },
    });

    return activities;
  }),

  // 创建活动
  create: protectedProcedure
    .input(
      z.object({
        name: z.string().min(1, "活动名称不能为空"),
        emoji: z.string().min(1, "请选择emoji"),
        color: z.string().min(1, "请选择颜色"),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      // 检查活动名称是否已存在
      const existingActivity = await prisma.activity.findFirst({
        where: {
          userId: ctx.user.userId,
          name: input.name,
        },
      });

      if (existingActivity) {
        throw new TRPCError({
          code: "CONFLICT",
          message: "活动名称已存在",
        });
      }

      const activity = await prisma.activity.create({
        data: {
          name: input.name,
          emoji: input.emoji,
          color: input.color,
          from: "user",
          userId: ctx.user.userId,
        },
      });

      return activity;
    }),

  // 开始活动
  start: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
        timeUnix: z.number().optional().describe("时间戳，单位：毫秒"),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      // 检查是否有未结束的period
      const unfinishedPeriod = await prisma.period.findFirst({
        where: {
          activityId: input.activityId,
          userId: ctx.user.userId,
          end: null,
        },
      });

      if (unfinishedPeriod) {
        throw new TRPCError({
          code: "CONFLICT",
          message: "该活动已在进行中",
        });
      }

      const startTime = input.timeUnix
        ? dayjs(input.timeUnix).toDate()
        : new Date();

      const period = await prisma.period.create({
        data: {
          start: startTime,
          activityId: input.activityId,
          userId: ctx.user.userId,
        },
      });

      return period;
    }),

  // 停止/暂停活动
  stop: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
        timeUnix: z.number().optional().describe("时间戳，单位：毫秒"),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const unfinishedPeriod = await prisma.period.findFirst({
        where: {
          activityId: input.activityId,
          userId: ctx.user.userId,
          end: null,
        },
      });

      if (!unfinishedPeriod) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "没有进行中的活动",
        });
      }

      const endTime = input.timeUnix ? new Date(input.timeUnix) : new Date();
      const duration = endTime.getTime() - unfinishedPeriod.start.getTime();

      const period = await prisma.period.update({
        where: { id: unfinishedPeriod.id },
        data: {
          end: endTime,
          duration: Math.floor(duration),
        },
      });

      return period;
    }),

  // 更新活动
  update: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
        name: z.string().min(1, "活动名称不能为空").optional(),
        emoji: z.string().min(1, "请选择emoji").optional(),
        color: z.string().min(1, "请选择颜色").optional(),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const activity = await prisma.activity.findUnique({
        where: { id: input.activityId },
      });

      if (!activity) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "未找到活动",
        });
      }

      if (activity.from === "system") {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "不能修改系统活动",
        });
      }

      if (activity.userId !== ctx.user.userId) {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "无权修改此活动",
        });
      }

      // 如果更新名称，检查是否已存在
      if (input.name && input.name !== activity.name) {
        const existingActivity = await prisma.activity.findFirst({
          where: {
            name: input.name,
            userId: ctx.user.userId,
            id: { not: input.activityId },
          },
        });

        if (existingActivity) {
          throw new TRPCError({
            code: "CONFLICT",
            message: "活动名称已存在",
          });
        }
      }

      const updatedActivity = await prisma.activity.update({
        where: { id: input.activityId },
        data: input,
      });

      return updatedActivity;
    }),

  // 删除活动
  delete: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const activity = await prisma.activity.findUnique({
        where: { id: input.activityId },
      });

      if (!activity) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "未找到活动",
        });
      }

      if (activity.from === "system") {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "不能删除系统活动",
        });
      }

      if (activity.userId !== ctx.user.userId) {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "无权删除此活动",
        });
      }

      // 删除相关的periods和goals
      await prisma.period.deleteMany({
        where: { activityId: input.activityId },
      });

      await prisma.activityGoal.deleteMany({
        where: { activityId: input.activityId },
      });

      await prisma.activity.delete({
        where: { id: input.activityId },
      });

      return { success: true };
    }),

  getDefaultActivity: protectedProcedure.query(async ({ ctx }) => {
    let lastActivityId: string | undefined;

    const periods = await prisma.period.findMany({
      where: {
        start: {
          gte: dayjs().startOf("day").toDate(),
          lte: dayjs().endOf("day").toDate(),
        },
        userId: ctx.user.userId,
      },
      select: {
        activityId: true,
        end: true,
      },
      orderBy: {
        start: "asc",
      },
    });

    if (periods?.length) {
      lastActivityId = periods.find((p) => !p.end)?.activityId;
      if (!lastActivityId) lastActivityId = periods.at(-1)?.activityId;
    }

    return { data: lastActivityId };
  }),
});

import { protectedProcedure, router } from "../trpc";
import { prisma } from "../db";
import { z } from "zod";
import { TRPCError } from "@trpc/server";
import dayjs from "dayjs";

export const activityGoalRouter = router({
  // 获取所有目标
  getAll: protectedProcedure.query(async ({ ctx }) => {
    const goals = await prisma.activityGoal.findMany({
      where: { userId: ctx.user.userId },
      include: {
        activity: {
          select: {
            id: true,
            name: true,
            emoji: true,
            color: true,
          },
        },
      },
    });

    return goals;
  }),

  // 获取特定活动的目标
  getByActivity: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
      }),
    )
    .query(async ({ ctx, input }) => {
      const goals = await prisma.activityGoal.findMany({
        where: {
          activityId: input.activityId,
          userId: ctx.user.userId,
        },
        include: {
          activity: {
            select: {
              id: true,
              name: true,
              emoji: true,
              color: true,
            },
          },
        },
      });

      return goals;
    }),

  // 更新或创建目标
  upsert: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
        targetHours: z.number().min(0.1, "目标时间必须大于0.1小时"),
        period: z.enum(["day", "week", "month", "year"]),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      // 验证活动是否存在且用户有权限
      const activity = await prisma.activity.findUnique({
        where: { id: input.activityId },
      });

      if (!activity) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "未找到活动",
        });
      }

      if (activity.from !== "system" && activity.userId !== ctx.user.userId) {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "无权设置此活动的目标",
        });
      }

      const goal = await prisma.activityGoal.upsert({
        where: {
          activityId_userId_period: {
            activityId: input.activityId,
            userId: ctx.user.userId,
            period: input.period,
          },
        },
        update: {
          targetHours: input.targetHours,
        },
        create: {
          activityId: input.activityId,
          userId: ctx.user.userId,
          targetHours: input.targetHours,
          period: input.period,
        },
        include: {
          activity: {
            select: {
              id: true,
              name: true,
              emoji: true,
              color: true,
            },
          },
        },
      });

      return goal;
    }),

  // 删除目标
  delete: protectedProcedure
    .input(
      z.object({
        goalId: z.string(),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const goal = await prisma.activityGoal.findUnique({
        where: { id: input.goalId },
      });

      if (!goal) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "未找到目标",
        });
      }

      if (goal.userId !== ctx.user.userId) {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "无权删除此目标",
        });
      }

      await prisma.activityGoal.delete({
        where: { id: input.goalId },
      });

      return { success: true };
    }),

  // 获取目标进度
  getProgress: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
        period: z.enum(["day", "week", "month", "year"]),
      }),
    )
    .query(async ({ ctx, input }) => {
      // 获取目标
      const goal = await prisma.activityGoal.findUnique({
        where: {
          activityId_userId_period: {
            activityId: input.activityId,
            userId: ctx.user.userId,
            period: input.period,
          },
        },
      });

      if (!goal) {
        return null;
      }

      // 计算时间范围 - 使用用户时区
      const userTimezone = ctx.cookie.timezone || "UTC";
      const now = dayjs().tz(userTimezone);
      let startDate: string;
      let endDate: string;

      switch (input.period) {
        case "day":
          startDate = now.startOf("day").toISOString();
          endDate = now.endOf("day").toISOString();
          break;
        case "week":
          startDate = now.startOf("week").toISOString();
          endDate = now.endOf("week").toISOString();
          break;
        case "month":
          startDate = now.startOf("month").toISOString();
          endDate = now.endOf("month").toISOString();
          break;
        case "year":
          startDate = now.startOf("year").toISOString();
          endDate = now.endOf("year").toISOString();
          break;
      }

      // 计算实际时间
      const periods = await prisma.period.findMany({
        where: {
          activityId: input.activityId,
          userId: ctx.user.userId,
          start: {
            gte: startDate,
            lt: endDate,
          },
        },
      });

      const actualTime = periods.reduce((total, period) => {
        if (period.duration) {
          return total + period.duration;
        }
        if (period.end) {
          return total + (period.end.getTime() - period.start.getTime());
        }
        // 正在进行的period
        return total + (Date.now() - period.start.getTime());
      }, 0);

      const actualHours = actualTime / (1000 * 60 * 60);
      const progress = (actualHours / goal.targetHours) * 100;

      return {
        goal,
        actualHours,
        targetHours: goal.targetHours,
        progress: Math.min(progress, 100),
        isCompleted: actualHours >= goal.targetHours,
      };
    }),

  // 获取活动目标达成率详情（包含每日工作量计算）
  getGoalCompletionDetails: protectedProcedure
    .input(
      z.object({
        activityId: z.string(),
        period: z.enum(["day", "week", "month", "year"]).default("month"),
      }),
    )
    .query(async ({ ctx, input }) => {
      // 获取目标
      const goal = await prisma.activityGoal.findUnique({
        where: {
          activityId_userId_period: {
            activityId: input.activityId,
            userId: ctx.user.userId,
            period: input.period,
          },
        },
      });

      if (!goal) {
        return null;
      }

      // 计算时间范围 - 使用用户时区
      const userTimezone = ctx.cookie.timezone || "UTC";
      const now = dayjs().tz(userTimezone);
      let startDate: string;
      let endDate: string;
      let startOfToday: string;

      switch (input.period) {
        case "day":
          startDate = now.startOf("day").toISOString();
          endDate = now.endOf("day").toISOString();
          startOfToday = now.startOf("day").toISOString();
          break;
        case "week":
          startDate = now.startOf("week").toISOString();
          endDate = now.endOf("week").toISOString();
          startOfToday = now.startOf("day").toISOString();
          break;
        case "month":
          startDate = now.startOf("month").toISOString();
          endDate = now.endOf("month").toISOString();
          startOfToday = now.startOf("day").toISOString();
          break;
        case "year":
          startDate = now.startOf("year").toISOString();
          endDate = now.endOf("year").toISOString();
          startOfToday = now.startOf("day").toISOString();
          break;
      }

      // 获取当前总完成时间
      const currentRecords = await prisma.period.findMany({
        where: {
          userId: ctx.user.userId,
          activityId: input.activityId,
          start: {
            gte: startDate,
            lte: endDate,
          },
        },
      });

      const currentHours = currentRecords.reduce((sum, record) => {
        return (
          sum +
          (new Date(record.end || record.start).getTime() -
            new Date(record.start).getTime()) /
            (1000 * 60 * 60)
        );
      }, 0);

      // 获取截止到今天凌晨的完成时间
      const recordsAtStartOfDay = await prisma.period.findMany({
        where: {
          userId: ctx.user.userId,
          activityId: input.activityId,
          start: {
            gte: startDate,
            lte: startOfToday,
          },
        },
      });

      const hoursAtStartOfDay = recordsAtStartOfDay.reduce((sum, record) => {
        return (
          sum +
          (new Date(record.end || record.start).getTime() -
            new Date(record.start).getTime()) /
            (1000 * 60 * 60)
        );
      }, 0);

      // 计算完成率
      const completionRate =
        goal.targetHours > 0
          ? Math.min((currentHours / goal.targetHours) * 100, 100)
          : 0;

      // 计算剩余时间
      const remainingHours = Math.max(goal.targetHours - currentHours, 0);

      // 计算剩余天数（包括今天）
      const daysRemaining =
        now.endOf(input.period).diff(now.startOf("day"), "day") + 1;

      // 计算每日平均时间（基于今天凌晨的完成情况）
      const minHoursPerDay =
        daysRemaining > 0
          ? Math.max(goal.targetHours - hoursAtStartOfDay, 0) / daysRemaining
          : 0;
      const hasDailyTarget = minHoursPerDay > 0.0001;

      return {
        activityId: input.activityId,
        targetHours: goal.targetHours,
        currentHours,
        completionRate: Number(completionRate.toFixed(1)),
        remainingHours: Number(remainingHours.toFixed(1)),
        minHoursPerDay: Number(minHoursPerDay.toFixed(1)),
        dailyTargetRaw: minHoursPerDay,
        hasDailyTarget,
        isCompleted: currentHours >= goal.targetHours,
        period: input.period,
        daysRemaining,
        startDate,
        endDate,
      };
    }),
});

import { protectedProcedure, router } from "../trpc";
import { prisma } from "../db";
import { z } from "zod";

export const userRouter = router({
  getRoles: protectedProcedure.query(async ({ ctx }) => {
    const user = await prisma.user.findUnique({
      where: { id: ctx.user.userId },
      select: {
        roles: {
          select: {
            id: true,
            name: true,
          },
        },
      },
    });

    return user?.roles || [];
  }),

  updateProfile: protectedProcedure
    .input(
      z.object({
        name: z.string().optional(),
        email: z.string().email().optional(),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const user = await prisma.user.update({
        where: { id: ctx.user.userId },
        data: {
          name: input.name,
          email: input.email,
        },
        select: {
          id: true,
          email: true,
          name: true,
        },
      });

      return user;
    }),
});

import type { APIRoute } from "astro";
import { getAuthServer } from "~/worker/auth";
