import { setEnv } from "~/worker/env";

export const prerender = false;

// CORS headers for Chrome extension support
const getCORSHeaders = (request: Request): HeadersInit => {
  const origin = request.headers.get("origin");
  const allowedOrigins = [
    "http://localhost:4321",
    "http://localhost:4322",
    "https://focus.35iter.cn",
  ];

  // Allow chrome-extension:// origins
  const isAllowedOrigin = origin && (
    allowedOrigins.includes(origin) ||
    origin.startsWith("chrome-extension://")
  );

  return {
    "Access-Control-Allow-Origin": isAllowedOrigin ? origin! : allowedOrigins[0],
    "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Requested-With",
    "Access-Control-Allow-Credentials": "true",
    "Access-Control-Max-Age": "86400",
  };
};

export const OPTIONS: APIRoute = ({ request }) => {
  return new Response(null, {
    status: 204,
    headers: getCORSHeaders(request),
  });
};

export const ALL: APIRoute = ({ request, locals }) => {
  // @ts-expect-error runtime is not typed
  initPrisma(locals.runtime.env.DB);
  // @ts-expect-error runtime is not typed
  setEnv(locals.runtime.env);

  // Handle CORS preflight
  if (request.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: getCORSHeaders(request),
    });
  }

  const corsHeaders = getCORSHeaders(request);

  return getAuthServer().handler(request).then((response) => {
    // Add CORS headers to the response
    Object.entries(corsHeaders).forEach(([key, value]) => {
      response.headers.set(key, value);
    });
    return response;
  });
};

