import { protectedProcedure, router } from "../trpc";
import { prisma } from "../db";
import { z } from "zod";
import { TRPCError } from "@trpc/server";

export const authRouter = router({
  // 获取当前用户信息
  me: protectedProcedure.query(async ({ ctx }) => {
    const user = await prisma.user.findUnique({
      where: { id: ctx.user.id },
      select: {
        id: true,
        email: true,
        name: true,
        image: true,
      },
    });

    if (!user) {
      throw new TRPCError({
        code: "NOT_FOUND",
        message: "用户不存在",
      });
    }

    return user;
  }),

  // 更新用户信息
  updateProfile: protectedProcedure
    .input(
      z.object({
        name: z.string().optional(),
        email: z.string().email().optional(),
        theme: z.string().optional(),
      }),
    )
    .mutation(async ({ ctx, input }) => {
      const user = await prisma.user.update({
        where: { id: ctx.user.id },
        data: {
          ...(input.name !== undefined && { name: input.name }),
          ...(input.email !== undefined && { email: input.email }),
          ...(input.theme !== undefined && { theme: input.theme }),
        },
        select: {
          id: true,
          email: true,
          name: true,
          image: true,
        },
      });

      return user;
    }),

  // 删除账户
  deleteAccount: protectedProcedure.mutation(async ({ ctx }) => {
    // 删除用户（会级联删除相关数据）
    await prisma.user.delete({
      where: { id: ctx.user.id },
    });

    return { success: true };
  }),
});

import { createEffect, createMemo, For, Show } from "solid-js";
import type { Period } from "~/generated/prisma/client";
import dayjs from "dayjs";
import { useRecords } from "~/contexts/Records";

import { DurationLabel } from "~/components/common/records/DurationLabel";
import { DateLabel } from "~/components/common/records/DateLabel";
import { Card } from "~/components/common/common/Card";

type Activity = {
  id: string;
  name: string;
  emoji: string;
  color: string;
  tag: string;
};

type PeriodWithActivity = Period & {
  activity: Activity;
};

type GroupedPeriods = {
  date: string;
  periods: PeriodWithActivity[];
};

const groupPeriodsByDate = (
  periods?: PeriodWithActivity[],
): GroupedPeriods[] => {
  if (!periods) return [];

  const groups: Record<string, PeriodWithActivity[]> = {};

  periods.forEach((period) => {
    const date = new Date(period.start).toLocaleDateString();
    if (!groups[date]) groups[date] = [];
    groups[date].push(period);
  });

  return Object.entries(groups).map(([, periods]) => ({
    date: dayjs(periods.at(0)?.start).toISOString(),
    periods: periods.sort(
      (a, b) => new Date(b.start).getTime() - new Date(a.start).getTime(),
    ),
  }));
};

type PeriodCardProps = {
  period: PeriodWithActivity;
};

const PeriodCard = (props: PeriodCardProps) => {
  return (
    <Card>
      <div class="flex items-center justify-between">
        <div class="flex items-center space-x-3">
          <div
            class="flex h-10 w-10 items-center justify-center rounded-full text-xl"
            style={{ "background-color": `${props.period.activity.color}20` }}
          >
            {props.period.activity.emoji}
          </div>
          <div>
            <h4 class="text-heading text-base-content font-medium">
              {props.period.activity.name}
            </h4>
            <DateLabel start={props.period.start} end={props.period.end} />
          </div>
        </div>
        <div class="text-right">
          <DurationLabel duration={props.period.duration} />
          <div class="text-sm" style={{ color: props.period.activity.color }}>
            {props.period.activity.tag}
          </div>
        </div>
      </div>
    </Card>
  );
};

type DayGroupProps = {
  group: GroupedPeriods;
};

const DayGroup = (props: DayGroupProps) => (
  <div>
    <h3 class="text-heading mb-4 font-medium">
      <DateLabel.Label date={props.group.date} format="YYYY-MM-DD" />
    </h3>
    <div class="space-y-4">
      <For each={props.group.periods}>
        {(period: PeriodWithActivity) => <PeriodCard period={period} />}
      </For>
    </div>
  </div>
);

export const TimelineView = () => {
  const { allPeriods, selectedDate, setSelectedDate } = useRecords();

  const filteredPeriods = createMemo<PeriodWithActivity[]>(() => {
    const periods = allPeriods()?.periods || [];
    if (!selectedDate()) return [];

    return (periods as any).filter(
      (period: any) => dayjs(period.start).format("MM/DD") === selectedDate(),
    );
  });

  createEffect(() => {
    const _allPeriods = allPeriods();
    if (!_allPeriods?.periods?.length) return;
    if (!selectedDate()) {
      setSelectedDate(dayjs(_allPeriods.periods.at(-1)?.start).format("MM/DD"));

      return;
    }

    if (
      _allPeriods.periods.every(
        (period: any) => dayjs(period.start).format("MM/DD") !== selectedDate(),
      )
    ) {
      setSelectedDate(dayjs(_allPeriods.periods.at(-1)?.start).format("MM/DD"));

      return;
    }
  });
  const groupedPeriods = createMemo(() =>
    groupPeriodsByDate(filteredPeriods() as unknown as PeriodWithActivity[]),
  );

  return (
    <Show when={groupedPeriods().length}>
      <div class="space-y-8">
        <For each={groupedPeriods()}>
          {(group: GroupedPeriods) => <DayGroup group={group} />}
        </For>
      </div>
    </Show>
  );
};

